import{c as i,U as t,h as a,l as e}from"./chunks/framework.C0iWzFTI.js";const d="/blog/assets/1726969297206-cfafde41-9596-4367-996f-d39a20163796.CjT5iLh3.png",l="/blog/assets/1726989338257-58c317b2-459e-46e2-bad1-2ebd1f4128a7.HHVE6VNX.png",n="/blog/assets/1726989971988-207b1882-8fa6-4b93-a7d4-75df63ae414b.BgpibKSx.png",p="/blog/assets/image-20250308173743304.CGmpoT60.png",h="data:image/png;base64,",m=JSON.parse('{"title":"事务","description":"事务的隔离性和MVCC","frontmatter":{"description":"事务的隔离性和MVCC"},"headers":[],"relativePath":"3-数据库/MySQL/3-事务.md","filePath":"3-数据库/MySQL/3-事务.md"}'),r={name:"3-数据库/MySQL/3-事务.md"};function k(A,s,o,c,E,g){return t(),a("div",null,s[0]||(s[0]=[e('<h1 id="事务" tabindex="-1">事务 <a class="header-anchor" href="#事务" aria-label="Permalink to &quot;事务&quot;">​</a></h1><h2 id="一、前言" tabindex="-1">一、前言 <a class="header-anchor" href="#一、前言" aria-label="Permalink to &quot;一、前言&quot;">​</a></h2><p><img src="'+d+'" alt=""></p><p>其中原子性，通过 undo log 来保障，持久性通过 redo log 来保障。接下来，我们分析一下隔离性</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>在并发场景之下，可能会出现的问题：</p><ul><li>脏读，是指一个事务，读取到了另一个事务还没有提交的信息</li><li>不可重复读，在一个事务之中多次读取同一个数据，如果说前后两次读取到的数据不一致。</li><li>幻读，在一个事务内多次查询某个符合查询条件的记录数量，前后两次查询到的记录数量不一致</li></ul></div><p>为了解决这些问题，就有了隔离级别，在 MySQL 之中，提供了不同的隔离级别，隔离级别越高，安全性就会越高，但是性能就会越低</p><p><img src="'+l+'" alt=""></p><p>那么，MySQL 又是如何实现这些隔离级别的呢？</p><p>在 undo log 之中，提到了版本链，每条数据的更新都会同时记录一条 undo log，每个事务都会分配一个事务ID</p><p><img src="'+n+'" alt=""></p><p>对于读未提交来说，他可以读取到其他事务未提交的数据，所以直接读取记录的最新的版本就好了，对于可串行化，通过锁的方式来控制，如果事务始终对某行记录进行更新操作，其余事务如果想读取，必须等该事务提交之后，释放对应的锁，才能够读取到</p><p>而 读已提交 和 可重复读，都必须保证读到已经提交了的事务修改过的记录，假如另一个事务已经修改了记录但是尚未提交，是不能直接读取最新版本的记录的，核心问题就是需要判断一下版本链中那个版本是当前事务可见的。为此，提出 <code>ReadView</code>。</p><p>在 Read View 之中，包含了如下内容：</p><ul><li><code>m_ids</code>：生成 <code> ReadView</code> 时当前系统中活跃的读写事务的事务id列表</li><li><code>min_trx_id</code>：m_ids 中的最小值</li><li><code>max_trx_id</code>：m_ids 中的最大值</li><li><code>creator_trx_id</code>：生成该<code>ReadView</code>的事务的事务id</li></ul><p>当具备了 ReadView 的时候，我们来看一下，读取一条数据对应的流程</p><ul><li>如果被访问版本的 <code>trx_id</code> 属性值与 <code>ReadView</code> 中的 <code>creator_trx_id</code> 值相同，意味着当前事务在访问它自己修改过的记录，所以该版本可以被当前事务访问。</li><li>如果被访问版本的 <code>trx_id</code> 属性值小于当前系统活跃的最小事务ID，说明这个版本事务已经提交了，所以可以进行访问。</li><li>如果被访问版本的 <code>trx_id</code> 属性值大于或等于当前系统活跃的最大事务ID，表明生成该版本的事务在当前事务生成 <code>ReadView</code> 后才开启，所以该版本不可以被当前事务访问。</li><li>如果被访问版本的 <code>trx_id</code> 属性值在 <code>ReadView</code> 的 <code>min_trx_id</code> 和 <code>max_trx_id</code>之间，那就需要判断一下<code>trx_id</code>属性值是不是在<code>m_ids</code>列表中，如果在，说明创建<code>Rea dView</code>时生成该版本的事务还是活跃的，该版本不可以被访问；如果不在，说明创建<code>ReadView</code>时生成该版本的事务已经被提交，该版本可以被访问。</li></ul><p><img src="'+p+'" alt="image-20250308173743304"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>只读事务不分配trx_id（会分配一个假trx_id），只有涉及到数据更新才会分配事务ID。</p></div><p>那么 read view 是什么时候生成的呢？</p><ul><li><code>read committed</code>在每次一次进行普通select操作的时候生成一个ReadView</li><li><code>repeatable read</code>只在第一次进行普通select操作前生成一个ReadView，后面会复用这个<code>ReadView</code>，版本链不会发生变化，所以说不会出现重复读的问题。</li></ul><h2 id="二、案例" tabindex="-1">二、案例 <a class="header-anchor" href="#二、案例" aria-label="Permalink to &quot;二、案例&quot;">​</a></h2><p>下面以实际的案例分析一下具体的隔离级别</p><p>我现在有一张表 tt ，建表语句如下：</p><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">`  (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AUTO_INCREMENT,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `a`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">255</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `b`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">255</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">USING</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> BTREE,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  INDEX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `index_a_b`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`a`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`b`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">USING</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> BTREE</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ENGINE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> InnoDB;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="_2-1-隐式事务" tabindex="-1">2.1 隐式事务 <a class="header-anchor" href="#_2-1-隐式事务" aria-label="Permalink to &quot;2.1 隐式事务&quot;">​</a></h3><p>前提：T2 时刻是分配了事务ID，假设事务ID 是 100；表中初始化数据如下：</p><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">insert into</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">values</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>1）T3 ， Session2 生成 readView，此时活跃的事务ID为：100，在判断版本链的过程之中，最新的 a = 2，事务ID 为 100，处于活跃的事务ID列表之中，不可见，所以 a = 1</p><p>2）T5 ，Session2 生成了readView，此时没有活跃的事务ID，在判断版本链的时候，能够读取到最新的数据</p><table tabindex="0"><thead><tr><th>时间</th><th>session1</th><th>session2</th></tr></thead><tbody><tr><td>T1</td><td>begin</td><td></td></tr><tr><td>T2</td><td>update tt set a = 2 where id = 1;</td><td></td></tr><tr><td>T3</td><td></td><td>select * from tt; <br>此时读取到的数据，a 等于 1</td></tr><tr><td>T4</td><td>commit</td><td></td></tr><tr><td>T5</td><td></td><td>select * from tt;<br>此时读取到的数据，a 等于2</td></tr></tbody></table><h3 id="_2-2-读已提交" tabindex="-1">2.2 读已提交 <a class="header-anchor" href="#_2-2-读已提交" aria-label="Permalink to &quot;2.2 读已提交&quot;">​</a></h3><p>前提：T2 时刻是分配了事务ID，假设事务ID 是 100；表中初始化数据如下：</p><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">insert into</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">values</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol><li><p>T5 ，session2 生成了 ReadView，此时活跃的事务ID 为 100，记录不可见，所以 a = 1，</p></li><li><p>T6 ，session1事务提交了</p></li></ol><p>3）T7，此时 session2 <strong>重新生成了 ReadView</strong>，此时没有活跃的事务ID了，就可以认为最新的记录是可见的，此时 a = 2</p><table tabindex="0"><thead><tr><th>时间</th><th>session1</th><th>session2</th></tr></thead><tbody><tr><td>T1</td><td></td><td>set session transaction isolation level READ COMMITTED;</td></tr><tr><td>T2</td><td>begin</td><td></td></tr><tr><td>T3</td><td>update tt set a = 2 where id = 1;</td><td></td></tr><tr><td>T4</td><td></td><td>begin</td></tr><tr><td>T5</td><td></td><td>select * from tt; <br>此时读取到的数据，a 等于 1</td></tr><tr><td>T6</td><td>commit</td><td></td></tr><tr><td>T7</td><td></td><td>select * from tt;<br>此时读取到的数据，a 等于 2</td></tr></tbody></table><p>由于每一次都重新生成了 ReadView ，所以在读已提交的隔离级别之下，解决了脏读的问题，但是没有解决不可重复读和幻读的问题</p><h3 id="_2-3-可重复读" tabindex="-1">2.3 可重复读 <a class="header-anchor" href="#_2-3-可重复读" aria-label="Permalink to &quot;2.3 可重复读&quot;">​</a></h3><p>前提：T2 时刻是分配了事务ID，假设事务ID 是 100；表中初始化数据如下：</p><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">insert into</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">values</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>1）T4 ，session2 生成 ReadView，此时活跃的事务ID为 100</p><p>2）T5，session1 将事务提交了</p><p>3）T6，session2 复用了 T4 时刻生成的 ReadView ，就导致 T6 的时候，还是认为 事务ID 100 是活跃的，记录仍然是不可见</p><table tabindex="0"><thead><tr><th>时间</th><th>session1</th><th>session2</th></tr></thead><tbody><tr><td>T1</td><td>begin</td><td></td></tr><tr><td>T2</td><td>update tt set a = 2 where id = 1;</td><td></td></tr><tr><td>T3</td><td></td><td>begin</td></tr><tr><td>T4</td><td></td><td>select * from tt; <br>此时读取到的数据，a 等于 1</td></tr><tr><td>T5</td><td>commit</td><td></td></tr><tr><td>T6</td><td></td><td>select * from tt;<br>此时读取到的数据，a 等于1</td></tr></tbody></table><p><strong>结论一：在可重复读的隔离级别之下，已经解决了不可重复读的问题。</strong></p><p>接下来，看一下幻读的场景，表中的初始数据如下：</p><p><img src="'+h+'" alt="image-20250309161729430"></p><table tabindex="0"><thead><tr><th>时间</th><th>session1</th><th>session2</th></tr></thead><tbody><tr><td>T1</td><td>begin</td><td>begin</td></tr><tr><td>T2</td><td>select * from tt; <br>return：（1,1,1）（3,3,1）</td><td></td></tr><tr><td>T3</td><td></td><td>insert into tt values(2,2,2);</td></tr><tr><td>T4</td><td>select * from tt; <br>return：（1,1,1）（3,3,1）</td><td></td></tr><tr><td>T5</td><td></td><td>commit</td></tr><tr><td>T6</td><td>select * from tt; <br>return：（1,1,1）（3,3,1）</td><td></td></tr></tbody></table><p><strong>结论二：在可重复读的场景之下，使用 MVCC ，实际上解决了幻读的问题</strong></p><p>这里就有问题了，为什么上文之中提到了，在可重复读的隔离级别之下，还是有可能出现幻读的问题呢？</p><p>这里需要区分一下读取的两种方式：</p><ul><li>快照读：当通过 MVCC 生成的快照读取数据时，不会出现幻读的问题，</li><li>当前读，读取所有已经提交的记录的最新值，加锁的 SELECT 或者对数据进行增删改的时候都会进行当前读，这种情况是会出现幻读的问题</li></ul>',52)]))}const u=i(r,[["render",k]]);export{m as __pageData,u as default};
